=== FILE: rr_arbiter_props.sv ===
// Formal wrapper and properties for rr_arbiter, written from interface_spec.md.
// Immediate assertions only (open yosys front end). No assumptions on inputs.
module rr_arbiter_formal (
    input wire       clk,
    input wire       rst_n,
    input wire [2:0] req
);
    wire [2:0] grant;
    wire [1:0] last;

    rr_arbiter dut (
        .clk   (clk),
        .rst_n (rst_n),
        .req   (req),
        .grant (grant),
        .last  (last)
    );

    // ---------------- formal helpers ----------------
    reg f_past_valid;
    reg f_reset_done;
    reg [1:0] f_wait0, f_wait1, f_wait2;
    initial begin
        f_past_valid = 1'b0;
        f_reset_done = 1'b0;
        f_wait0 = 2'd0;
        f_wait1 = 2'd0;
        f_wait2 = 2'd0;
    end

    always @(posedge clk) begin
        f_past_valid <= 1'b1;
        if (!rst_n)
            f_reset_done <= 1'b1;
    end

    // Consecutive edges a requester has held req high without a grant.
    always @(posedge clk) begin
        if (!rst_n || !req[0] || grant[0]) f_wait0 <= 2'd0;
        else if (f_wait0 != 2'd3)          f_wait0 <= f_wait0 + 2'd1;
        if (!rst_n || !req[1] || grant[1]) f_wait1 <= 2'd0;
        else if (f_wait1 != 2'd3)          f_wait1 <= f_wait1 + 2'd1;
        if (!rst_n || !req[2] || grant[2]) f_wait2 <= 2'd0;
        else if (f_wait2 != 2'd3)          f_wait2 <= f_wait2 + 2'd1;
    end

    // Priority order from the spec: last+1, last+2, last (mod 3).
    wire [1:0] f_p0 = (last == 2'd0) ? 2'd1 : (last == 2'd1) ? 2'd2 : 2'd0;
    wire [1:0] f_p1 = (last == 2'd0) ? 2'd2 : (last == 2'd1) ? 2'd0 : 2'd1;
    wire [1:0] f_p2 = last;
    wire [2:0] f_oh0 = 3'b001 << f_p0;
    wire [2:0] f_oh1 = 3'b001 << f_p1;
    wire [2:0] f_oh2 = 3'b001 << f_p2;

    // ---------------- combinational properties ----------------
    always @(*) begin
        // [req:RR-IDLE]
        if (req == 3'b000)
            assert (grant == 3'b000);
        // [req:RR-PICK] exactly one bit high when any request
        if (req != 3'b000)
            assert (grant == 3'b001 || grant == 3'b010 || grant == 3'b100);
        // [req:RR-ONLY-REQUESTERS]
        assert ((grant & ~req) == 3'b000);
    end

    always @(*) begin
        if (f_reset_done) begin
            // helper invariant: last is a requester index
            assert (last != 2'd3);
            // [req:RR-PICK] first requester in priority order
            if (req[f_p0])
                assert (grant == f_oh0);
            if (!req[f_p0] && req[f_p1])
                assert (grant == f_oh1);
            if (!req[f_p0] && !req[f_p1] && req[f_p2])
                assert (grant == f_oh2);
            // helper invariants for the bound
            assert (f_wait0 <= 2'd2);
            assert (f_wait1 <= 2'd2);
            assert (f_wait2 <= 2'd2);
            // [req:RR-BOUND] granted on the third edge of a held request
            if (f_wait0 == 2'd2 && req[0])
                assert (grant[0]);
            if (f_wait1 == 2'd2 && req[1])
                assert (grant[1]);
            if (f_wait2 == 2'd2 && req[2])
                assert (grant[2]);
        end
    end

    // ---------------- clocked properties ----------------
    always @(posedge clk) begin
        if (f_past_valid) begin
            // [req:RR-RESET]
            if (!$past(rst_n))
                assert (last == 2'd2);
            // [req:RR-ROTATE]
            if ($past(rst_n) && $past(grant[0]))
                assert (last == 2'd0);
            if ($past(rst_n) && $past(grant[1]))
                assert (last == 2'd1);
            if ($past(rst_n) && $past(grant[2]))
                assert (last == 2'd2);
            // [req:RR-HOLD]
            if ($past(rst_n) && ($past(grant) == 3'b000))
                assert (last == $past(last));
            // [req:RR-YIELD]
            if ($past(rst_n) && $past(grant[0]) && (req[2:1] != 2'b00))
                assert (!grant[0]);
            if ($past(rst_n) && $past(grant[1]) && ((req & 3'b101) != 3'b000))
                assert (!grant[1]);
            if ($past(rst_n) && $past(grant[2]) && (req[1:0] != 2'b00))
                assert (!grant[2]);
        end
    end

    // ---------------- covers ----------------
    always @(posedge clk) begin
        if (f_past_valid) begin
            cover (f_reset_done && req == 3'b111 && grant == 3'b001);
            cover (f_reset_done && req == 3'b111 && grant == 3'b010);
            cover (f_reset_done && req == 3'b111 && grant == 3'b100);
            cover (f_reset_done && req == 3'b000);
            cover (f_reset_done && $past(rst_n) && $past(grant) == 3'b000);
            cover (f_reset_done && $past(rst_n) && $past(grant[0]) && grant[1]);
            cover (f_reset_done && $past(rst_n) && $past(grant[1]) && grant[2]);
            cover (f_reset_done && $past(rst_n) && $past(grant[2]) && grant[0]);
            cover (f_reset_done && f_wait0 == 2'd2 && req[0]);
            cover (f_reset_done && f_wait1 == 2'd2 && req[1]);
            cover (f_reset_done && f_wait2 == 2'd2 && req[2]);
        end
    end
endmodule
=== END FILE ===
